Ltac slia_atom := first [ exact I | assumption | match goal with K : chunk_disj _ _ _ _ |- _ => exact K end
                        | lazymatch goal with |- not _ => intros ?; repeat match goal with K : _ /\ _ |- _ => destruct K end;
                                                          match goal with K : not _ |- _ => apply K; split; lia_t1 end end
                        | dj_lia ].
Ltac slia_conj := first [ exact I | lazymatch goal with |- _ /\ _ => split; [slia_atom| slia_conj] end | slia_atom ].
Ltac slia ::= slia_conj.

(* [comment removed for export] *)
Ltac wseed H l h :=
  let go A2 s2 := (let W := fresh "WS" in assert (W : hideL (A2 + s2 <= l \/ h <= A2)); [unfold hideL|]) in
  lazymatch type of H with
  | rw_cells _ _ ?A2 ?cs2 => let s2 := dj_size_cells cs2 in go A2 s2
  | ro_cells _ _ ?A2 ?cs2 => let s2 := dj_size_cells cs2 in go A2 s2
  end.


