    (m m0 mx : mem) (lowpad high : list cell) (hjunk sh32 : list byte) (bflag : byte),
  rw_cells bsegs mx spa lowpad -> Z.of_nat (cells_size lowpad) = 16 -> lo <= spa ->
  rw_cells bsegs mx (spa + 16) [C8 (Z_to_bv 64 ff); C8 t24; C8 t32] ->
  rw_cells bsegs mx (spa + 40) high -> Z.of_nat (cells_size high) = bv_unsigned sp + -128 - spa ->
  rw_cells bsegs mx (bv_unsigned sp + -88) (cl_saved s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs mx ff [CB 248 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 32 sh32] ->
  rw_cells bsegs mx fp [C1 bflag] ->
  stk bsegs mx lo spa -> mem_inv bsegs mx ->
  as_RFS H ((2, ff, fp) :: LF) mx -> fresh_frame H LF 2 ff fp -> ACONST mx -> stack0 mx lo shi ->
  as_RFS H LF m0 ->
  munch (cl_W H lo sp bs stb ff fp) m mx -> wmono bsegs m mx ->
  rw_cells bsegs mx bs (BasicStreamCells stb) ->
  AStateBlock LB mx stb ioc implb (st_closed S) ds -> fsobj H LF stb SZ_SPCI_STATE ->
  (st_fb S <> FB_empty -> fsobj H LF (fb_begin (st_fb S)) (fb_cap (st_fb S))) ->
  accessible mx bs SZ_BS -> aplace bs SZ_BS -> fsobj H LF bs SZ_BS -> (bs + SZ_BS <= stb \/ stb + SZ_SPCI_STATE <= bs) ->
  (bs + SZ_BS <= lo \/ bv_unsigned sp <= bs) ->
  lo + 144 <= bv_unsigned sp -> spa + 128 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (stream_close_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB LF bs stb ioc implb lo shi S ds m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
