(* [comment removed for export] *)
Ltac cl_bundle_now HH RFc ACc SK2 FF MU3 WM3 W3K RFx ACx SKx :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    lazymatch type of SK2 with stack0 _ ?lo ?shi => lazymatch type of RFc with as_RFS ?H ?LFc _ =>
    let B := fresh "BND" in
    assert (B : as_RFS H LFc mc /\ ACONST mc /\ stack0 mc lo shi)
      by (eapply (fs_frame_writes_pl _ HH); [exact RFc| exact ACc| exact SK2| exact FF| exact MU3| exact WM3| exact W3K]);
    destruct B as (RFx & ACx & SKx) end end end.

(* [comment removed for export] *)
Ltac cl_acc_now AC MU3 WFR F1 F3 SEP ACn :=
  lazymatch type of AC with accessible _ ?O ?n =>
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    assert (ACn : accessible mc O n)
      by (eapply (accessible_transport_fr _ _ mc O n _ 32); [exact AC| exact MU3| exact WFR| clear - F1; lia| exact F3| clear; lia| clear - SEP; unhideL; lia])
  end end.

